css:
.foresight-sim-container {
    padding: 28px;
    background: radial-gradient(ellipse at top, #132544 0%, #0a1628 55%, #060c1a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6edf7;
}

.foresight-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 24px;
    border-bottom: 1px solid rgba(245, 158, 11, 0.25);
    padding-bottom: 22px;
    margin-bottom: 26px;
}
.foresight-sim-header-brand {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.foresight-sim-badge {
    align-self: flex-start;
    background: linear-gradient(90deg, rgba(245, 158, 11, 0.25), rgba(245, 158, 11, 0.05));
    color: #f59e0b;
    border: 1px solid rgba(245, 158, 11, 0.45);
    padding: 4px 10px;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    border-radius: 3px;
    font-weight: 600;
}
.foresight-sim-header h1 {
    margin: 0;
    font-size: 2rem;
    font-weight: 700;
    color: #f8fafc;
    letter-spacing: -0.01em;
}
.foresight-sim-header-meta {
    text-align: right;
}
.foresight-sim-company {
    font-size: 0.85rem;
    color: #94a3b8;
    letter-spacing: 0.04em;
    margin-bottom: 8px;
}
.foresight-sim-period-counter {
    font-size: 0.95rem;
    color: #06b6d4;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.foresight-sim-period-counter span {
    padding: 0 3px;
}

.foresight-sim-briefing {
    background: linear-gradient(135deg, rgba(30, 58, 138, 0.35) 0%, rgba(6, 182, 212, 0.12) 100%);
    border: 1px solid rgba(6, 182, 212, 0.35);
    border-left: 4px solid #06b6d4;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.foresight-sim-briefing-tag {
    color: #06b6d4;
    font-size: 0.68rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 8px;
}
.foresight-sim-briefing h2 {
    margin: 0 0 6px 0;
    color: #f8fafc;
    font-size: 1.4rem;
    font-weight: 600;
}
.foresight-sim-briefing-months {
    font-size: 0.8rem;
    color: #94a3b8;
    letter-spacing: 0.08em;
    margin-bottom: 14px;
}
.foresight-sim-briefing-text {
    color: #cbd5e1;
    font-size: 0.98rem;
    line-height: 1.6;
    margin-bottom: 12px;
}
.foresight-sim-briefing-deliverable {
    font-size: 0.85rem;
    color: #f59e0b;
    font-style: italic;
    padding-top: 10px;
    border-top: 1px dashed rgba(245, 158, 11, 0.3);
}

.foresight-sim-event-panel {
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.18) 0%, rgba(245, 158, 11, 0.08) 100%);
    border: 1px solid rgba(239, 68, 68, 0.45);
    border-left: 4px solid #ef4444;
    border-radius: 10px;
    padding: 18px 22px;
    margin-bottom: 22px;
    animation: foresightPulse 2.4s ease-in-out;
}
@keyframes foresightPulse {
    0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
    30% { box-shadow: 0 0 22px 2px rgba(239, 68, 68, 0.35); }
    100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}
.foresight-sim-event-tag {
    color: #ef4444;
    font-size: 0.7rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 6px;
}
.foresight-sim-event-title {
    color: #f8fafc;
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 6px;
}
.foresight-sim-event-text {
    color: #e2e8f0;
    font-size: 0.92rem;
    line-height: 1.5;
}

.foresight-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.foresight-sim-kpi-card {
    background: rgba(15, 23, 42, 0.78);
    border: 1px solid rgba(148, 163, 184, 0.15);
    border-radius: 10px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, border-color 0.2s ease;
}
.foresight-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: rgba(245, 158, 11, 0.35);
}
.foresight-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #f59e0b, #06b6d4);
}
.foresight-sim-kpi-label {
    font-size: 0.7rem;
    color: #94a3b8;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.foresight-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #f8fafc;
    line-height: 1.1;
    margin-bottom: 4px;
}
.foresight-sim-kpi-unit {
    font-size: 0.72rem;
    color: #64748b;
    letter-spacing: 0.05em;
}
.foresight-sim-kpi-foresight .foresight-sim-kpi-value { color: #06b6d4; }
.foresight-sim-kpi-robustness .foresight-sim-kpi-value { color: #22c55e; }
.foresight-sim-kpi-option .foresight-sim-kpi-value { color: #f59e0b; }
.foresight-sim-kpi-confidence .foresight-sim-kpi-value { color: #a78bfa; }
.foresight-sim-kpi-npv .foresight-sim-kpi-value { color: #facc15; }
.foresight-sim-kpi-stranded .foresight-sim-kpi-value { color: #f87171; }

.foresight-sim-controls {
    background: rgba(15, 23, 42, 0.72);
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 12px;
    padding: 26px;
    margin-bottom: 26px;
}
.foresight-sim-controls h3 {
    margin: 0 0 20px 0;
    color: #f8fafc;
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(245, 158, 11, 0.25);
    padding-bottom: 10px;
}
.foresight-sim-field {
    margin-bottom: 18px;
}
.foresight-sim-field label {
    display: block;
    font-size: 0.82rem;
    color: #cbd5e1;
    font-weight: 600;
    margin-bottom: 6px;
    letter-spacing: 0.04em;
}
.foresight-sim-field input[type="number"],
.foresight-sim-field select,
.foresight-sim-controls input[type="number"],
.foresight-sim-controls select {
    background: #0a1628;
    border: 1px solid #2d3f55;
    color: #e6edf7;
    border-radius: 6px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.foresight-sim-field input[type="number"]:focus,
.foresight-sim-field select:focus {
    outline: none;
    border-color: #06b6d4;
    box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.2);
}
.foresight-sim-controls select option,
.foresight-sim-field select option {
    background: #0a1628;
    color: #e6edf7;
    padding: 8px;
}
.foresight-sim-help {
    margin-top: 5px;
    font-size: 0.78rem;
    color: #94a3b8;
    line-height: 1.4;
}
.foresight-sim-field-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.foresight-sim-field-col { display: flex; flex-direction: column; }

.foresight-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    padding-top: 18px;
    border-top: 1px solid rgba(148, 163, 184, 0.15);
}
.foresight-sim-submit {
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    border: none;
    color: #0a1628;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 12px 26px;
    border-radius: 6px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.foresight-sim-submit:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 18px rgba(245, 158, 11, 0.35);
    color: #0a1628;
}
.foresight-sim-undo {
    background: transparent;
    border: 1px solid rgba(148, 163, 184, 0.4);
    color: #cbd5e1;
    letter-spacing: 0.05em;
}
.foresight-sim-undo:hover {
    background: rgba(148, 163, 184, 0.1);
    color: #f8fafc;
}

.foresight-sim-hint-box {
    background: rgba(167, 139, 250, 0.1);
    border: 1px solid rgba(167, 139, 250, 0.35);
    border-left: 4px solid #a78bfa;
    border-radius: 8px;
    padding: 14px 18px;
    margin-bottom: 24px;
    color: #e0e7ff;
    font-size: 0.92rem;
    line-height: 1.55;
}
.foresight-sim-hint-tag {
    display: inline-block;
    color: #a78bfa;
    font-size: 0.66rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    font-weight: 700;
    margin-right: 10px;
}

.foresight-sim-charts {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 20px;
    margin-bottom: 26px;
}
.foresight-sim-chart-card {
    background: rgba(15, 23, 42, 0.78);
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 10px;
    padding: 20px;
    position: relative;
    min-height: 320px;
}
.foresight-sim-chart-title {
    font-size: 0.78rem;
    color: #94a3b8;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 14px;
}
.foresight-sim-chart-card canvas {
    max-height: 260px;
}

.foresight-sim-history {
    background: rgba(15, 23, 42, 0.72);
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 10px;
    padding: 22px;
    margin-bottom: 10px;
}
.foresight-sim-history-title {
    font-size: 0.78rem;
    color: #94a3b8;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 16px;
}
.foresight-sim-history #usfHistoryTable {
    color: #e6edf7;
    background: transparent;
    margin: 0;
    width: 100%;
}
.foresight-sim-history #usfHistoryTable thead th {
    background: rgba(6, 182, 212, 0.12);
    color: #06b6d4;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(6, 182, 212, 0.3);
    border-top: none;
    padding: 10px 12px;
    font-weight: 700;
}
.foresight-sim-history #usfHistoryTable tbody td {
    padding: 10px 12px;
    border-top: 1px solid rgba(148, 163, 184, 0.1);
    font-size: 0.9rem;
    color: #cbd5e1;
}
.foresight-sim-history #usfHistoryTable tbody tr:hover {
    background: rgba(245, 158, 11, 0.06);
}

@media (max-width: 768px) {
    .foresight-sim-container { padding: 16px; }
    .foresight-sim-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }
    .foresight-sim-header-meta { text-align: left; }
    .foresight-sim-header h1 { font-size: 1.5rem; }
    .foresight-sim-field-row { grid-template-columns: 1fr; }
    .foresight-sim-charts { grid-template-columns: 1fr; }
    .foresight-sim-kpi-value { font-size: 1.6rem; }
    .foresight-sim-actions { flex-direction: column; }
}

