(function() {
    'use strict';

    class ForesightLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `ForesightLab`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                {
                    idx: 0,
                    primaryOptions: [
                        { value: `technology`, i18n: `opt_tech` },
                        { value: `regulatory`, i18n: `opt_reg` },
                        { value: `competitive`, i18n: `opt_comp` },
                        { value: `macro`, i18n: `opt_macro` }
                    ],
                    secondaryOptions: [
                        { value: `technology`, i18n: `opt_tech` },
                        { value: `regulatory`, i18n: `opt_reg` },
                        { value: `competitive`, i18n: `opt_comp` },
                        { value: `macro`, i18n: `opt_macro` }
                    ],
                    defaultPrimary: `technology`,
                    defaultSecondary: `regulatory`,
                    defaultCommit: 60,
                    defaultReserve: 80
                },
                {
                    idx: 1,
                    primaryOptions: [
                        { value: `speed_tech`, i18n: `opt_axis_speed_tech` },
                        { value: `reg_disrupt`, i18n: `opt_axis_reg_disrupt` },
                        { value: `geo_fin`, i18n: `opt_axis_geo_fin` },
                        { value: `social_econ`, i18n: `opt_axis_social_econ` }
                    ],
                    secondaryOptions: [
                        { value: `bold`, i18n: `opt_anchor_bold` },
                        { value: `moderate`, i18n: `opt_anchor_moderate` },
                        { value: `conservative`, i18n: `opt_anchor_conservative` }
                    ],
                    defaultPrimary: `speed_tech`,
                    defaultSecondary: `bold`,
                    defaultCommit: 80,
                    defaultReserve: 120
                },
                {
                    idx: 2,
                    primaryOptions: [
                        { value: `legacy`, i18n: `opt_scen_legacy` },
                        { value: `disrupted`, i18n: `opt_scen_disrupted` },
                        { value: `divergent`, i18n: `opt_scen_divergent` },
                        { value: `abundance`, i18n: `opt_scen_abundance` },
                        { value: `balanced`, i18n: `opt_scen_balanced` }
                    ],
                    secondaryOptions: [
                        { value: `deep`, i18n: `opt_depth_deep` },
                        { value: `moderate`, i18n: `opt_depth_moderate` },
                        { value: `light`, i18n: `opt_depth_light` }
                    ],
                    defaultPrimary: `balanced`,
                    defaultSecondary: `moderate`,
                    defaultCommit: 120,
                    defaultReserve: 140
                },
                {
                    idx: 3,
                    primaryOptions: [
                        { value: `aggressive_green`, i18n: `opt_port_green` },
                        { value: `balanced`, i18n: `opt_port_balanced` },
                        { value: `gas_bridge`, i18n: `opt_port_gas` },
                        { value: `regional`, i18n: `opt_port_regional` },
                        { value: `harvest`, i18n: `opt_port_harvest` }
                    ],
                    secondaryOptions: [
                        { value: `peru_chile`, i18n: `opt_geo_pc` },
                        { value: `colombia_mexico`, i18n: `opt_geo_cm` },
                        { value: `brazil`, i18n: `opt_geo_br` },
                        { value: `diversified`, i18n: `opt_geo_div` }
                    ],
                    defaultPrimary: `balanced`,
                    defaultSecondary: `diversified`,
                    defaultCommit: 220,
                    defaultReserve: 160
                },
                {
                    idx: 4,
                    primaryOptions: [
                        { value: `defer`, i18n: `opt_opt_defer` },
                        { value: `pilot`, i18n: `opt_opt_pilot` },
                        { value: `reversible`, i18n: `opt_opt_reversible` },
                        { value: `trigger`, i18n: `opt_opt_trigger` },
                        { value: `mixed`, i18n: `opt_opt_mixed` }
                    ],
                    secondaryOptions: [
                        { value: `quarterly`, i18n: `opt_gov_quarterly` },
                        { value: `annual`, i18n: `opt_gov_annual` },
                        { value: `ad_hoc`, i18n: `opt_gov_adhoc` }
                    ],
                    defaultPrimary: `mixed`,
                    defaultSecondary: `quarterly`,
                    defaultCommit: 140,
                    defaultReserve: 220
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    foresightQuality: 50,
                    strategicRobustness: 50,
                    optionValue: 0,
                    boardConfidence: 50,
                    portfolioNPV: 0,
                    strandedRisk: 0,
                    activeEvent: null,
                    lastHint: null,
                    foresightHistory: [],
                    robustnessHistory: [],
                    optionHistory: [],
                    confidenceHistory: [],
                    npvHistory: [],
                    strandedHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primaryFocus: `technology`,
                    secondaryFocus: `regulatory`,
                    capitalCommit: 60,
                    optionalityReserve: 80,
                    narrativeApproach: `balanced`
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 60);
        }

        validateDecisions(decisions) {
            var s = window.mySimulation.state;
            this._updateBriefing(s);

            var primarySel = document.getElementById(`primaryFocus`);
            var secondarySel = document.getElementById(`secondaryFocus`);
            var commitInp = document.getElementById(`capitalCommit`);
            var reserveInp = document.getElementById(`optionalityReserve`);
            var narrativeSel = document.getElementById(`narrativeApproach`);

            if (primarySel) decisions.primaryFocus = primarySel.value;
            if (secondarySel) decisions.secondaryFocus = secondarySel.value;
            if (commitInp) decisions.capitalCommit = parseFloat(commitInp.value);
            if (reserveInp) decisions.optionalityReserve = parseFloat(reserveInp.value);
            if (narrativeSel) decisions.narrativeApproach = narrativeSel.value;

            if (isNaN(decisions.capitalCommit) || decisions.capitalCommit < 0 || decisions.capitalCommit > 500) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`capital_warning`), `warning`
                );
                return false;
            }
            if (isNaN(decisions.optionalityReserve) || decisions.optionalityReserve < 0 || decisions.optionalityReserve > 500) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`reserve_warning`), `warning`
                );
                return false;
            }
            if ((decisions.capitalCommit + decisions.optionalityReserve) > 600) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`total_warning`), `warning`
                );
                return false;
            }
            if (!decisions.primaryFocus || !decisions.secondaryFocus) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`focus_warning`), `warning`
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = (state.currentPeriod || 1) - 1;
            if (roundIdx < 0) roundIdx = 0;
            if (roundIdx > 4) roundIdx = 4;

            var commit = d.capitalCommit;
            var reserve = d.optionalityReserve;
            var total = commit + reserve;
            var optionalityShare = total > 0 ? reserve / total : 0;

            var eventKey = this._rollEvent(roundIdx);
            ds.activeEvent = eventKey;

            var foresightDelta = 0;
            var robustnessDelta = 0;
            var optionDelta = 0;
            var confidenceDelta = 0;
            var npvDelta = 0;
            var strandedDelta = 0;

            var differentFocus = (d.primaryFocus !== d.secondaryFocus);

            if (roundIdx === 0) {
                foresightDelta = 6 + (differentFocus ? 8 : -2);
                if (reserve >= 40 && reserve <= 140) foresightDelta += 4;
                if (commit > 180) foresightDelta -= 6;
                robustnessDelta = differentFocus ? 3 : -1;
                optionDelta = reserve * 0.35;
                confidenceDelta = (d.narrativeApproach === `data`) ? 4 : (d.narrativeApproach === `balanced` ? 2 : -1);
                npvDelta = -commit * 0.2 + reserve * 0.05;
                strandedDelta = commit > 200 ? (commit - 200) * 0.4 : 0;
            } else if (roundIdx === 1) {
                var goodAxis = (d.primaryFocus === `speed_tech` || d.primaryFocus === `reg_disrupt`);
                foresightDelta = goodAxis ? 10 : 2;
                if (d.secondaryFocus === `bold`) foresightDelta += 4;
                if (d.secondaryFocus === `conservative`) foresightDelta -= 3;
                robustnessDelta = goodAxis ? 6 : 1;
                optionDelta = reserve * 0.3;
                confidenceDelta = (d.narrativeApproach === `narrative`) ? 5 : (d.narrativeApproach === `balanced` ? 3 : 0);
                npvDelta = -commit * 0.15;
                strandedDelta = (d.secondaryFocus === `conservative` ? 10 : 0);
            } else if (roundIdx === 2) {
                if (d.primaryFocus === `balanced`) {
                    foresightDelta = 12;
                    robustnessDelta = 10;
                } else {
                    foresightDelta = 4;
                    robustnessDelta = -4;
                    strandedDelta += 25;
                }
                if (d.secondaryFocus === `deep`) { foresightDelta += 3; npvDelta -= 20; }
                else if (d.secondaryFocus === `light`) { foresightDelta -= 4; robustnessDelta -= 3; }
                optionDelta = reserve * 0.28;
                confidenceDelta = (d.narrativeApproach === `balanced` || d.narrativeApproach === `narrative`) ? 5 : 1;
                if (eventKey === `cbam_regulatory`) {
                    if (d.primaryFocus === `balanced` || d.primaryFocus === `disrupted`) {
                        foresightDelta += 8;
                        confidenceDelta += 4;
                    } else if (d.primaryFocus === `legacy`) {
                        robustnessDelta -= 10;
                        strandedDelta += 40;
                    }
                }
                npvDelta += -commit * 0.18;
            } else if (roundIdx === 3) {
                var portfolio = d.primaryFocus;
                if (portfolio === `balanced`) {
                    robustnessDelta = 14;
                    npvDelta = commit * 0.45 - 30;
                } else if (portfolio === `aggressive_green`) {
                    robustnessDelta = 6;
                    npvDelta = commit * 0.35 - 40;
                    if (ds.foresightQuality >= 70) robustnessDelta += 4;
                } else if (portfolio === `gas_bridge`) {
                    robustnessDelta = -2;
                    npvDelta = commit * 0.6 - 20;
                    strandedDelta += 50;
                } else if (portfolio === `regional`) {
                    robustnessDelta = 4;
                    npvDelta = commit * 0.4 - 30;
                } else if (portfolio === `harvest`) {
                    robustnessDelta = -6;
                    npvDelta = commit * 0.7;
                    strandedDelta += 80;
                }
                foresightDelta = 3;
                if (d.secondaryFocus === `diversified`) { robustnessDelta += 5; }
                else if (d.secondaryFocus === `brazil`) { robustnessDelta += 2; }
                else { robustnessDelta -= 2; strandedDelta += 15; }
                optionDelta = reserve * 0.25;
                confidenceDelta = (d.narrativeApproach === `data`) ? 6 : (d.narrativeApproach === `balanced` ? 4 : 2);
                if (eventKey === `tech_breakthrough`) {
                    if (portfolio === `aggressive_green` || portfolio === `balanced`) {
                        robustnessDelta += 10;
                        npvDelta += 60;
                        confidenceDelta += 6;
                    } else if (portfolio === `gas_bridge` || portfolio === `harvest`) {
                        robustnessDelta -= 12;
                        strandedDelta += 80;
                        confidenceDelta -= 8;
                    }
                }
                if (eventKey === `geopolitical_shock`) {
                    // Mexico nationalization + 35% peso devaluation: geographic exposure
                    // (secondaryFocus) determines how hard the shock lands.
                    if (d.secondaryFocus === `diversified`) {
                        robustnessDelta += 6;
                        confidenceDelta += 3;
                    } else if (d.secondaryFocus === `colombia_mexico`) {
                        robustnessDelta -= 12;
                        strandedDelta += 55;
                        npvDelta -= 40;
                        confidenceDelta -= 5;
                    } else if (d.secondaryFocus === `peru_chile`) {
                        robustnessDelta -= 4;
                        strandedDelta += 20;
                        npvDelta -= 15;
                    } else if (d.secondaryFocus === `brazil`) {
                        robustnessDelta += 2;
                    }
                }
            } else if (roundIdx === 4) {
                var optionMode = d.primaryFocus;
                if (optionMode === `mixed`) { foresightDelta = 6; robustnessDelta = 10; optionDelta = reserve * 0.5; }
                else if (optionMode === `defer`) { robustnessDelta = 5; optionDelta = reserve * 0.55; npvDelta -= 15; }
                else if (optionMode === `pilot`) { robustnessDelta = 7; optionDelta = reserve * 0.45; npvDelta += commit * 0.15; }
                else if (optionMode === `reversible`) { robustnessDelta = 8; optionDelta = reserve * 0.4; }
                else if (optionMode === `trigger`) { robustnessDelta = 9; optionDelta = reserve * 0.42; foresightDelta += 4; }
                if (d.secondaryFocus === `quarterly`) { foresightDelta += 5; confidenceDelta += 6; }
                else if (d.secondaryFocus === `annual`) { foresightDelta += 2; confidenceDelta += 2; }
                else { confidenceDelta -= 3; robustnessDelta -= 4; }
                confidenceDelta += (d.narrativeApproach === `narrative`) ? 8 : (d.narrativeApproach === `balanced` ? 5 : 2);
                npvDelta += commit * 0.3;
                if (eventKey === `black_swan`) {
                    if (optionMode === `mixed` || optionMode === `trigger` || optionMode === `pilot`) {
                        robustnessDelta += 14;
                        confidenceDelta += 10;
                        foresightDelta += 6;
                    } else {
                        robustnessDelta -= 10;
                        strandedDelta += 60;
                        confidenceDelta -= 6;
                    }
                }
            }

            if (optionalityShare > 0.6) {
                foresightDelta += 2;
                robustnessDelta += 2;
            } else if (optionalityShare < 0.2) {
                strandedDelta += 15;
                robustnessDelta -= 3;
            }

            ds.foresightQuality = Math.max(0, Math.min(100, ds.foresightQuality + foresightDelta));
            ds.strategicRobustness = Math.max(0, Math.min(100, ds.strategicRobustness + robustnessDelta));
            ds.optionValue = Math.max(0, ds.optionValue + optionDelta);
            ds.boardConfidence = Math.max(0, Math.min(100, ds.boardConfidence + confidenceDelta));
            ds.portfolioNPV = ds.portfolioNPV + npvDelta;
            ds.strandedRisk = Math.max(0, ds.strandedRisk + strandedDelta);

            ds.foresightHistory.push(Math.round(ds.foresightQuality));
            ds.robustnessHistory.push(Math.round(ds.strategicRobustness));
            ds.optionHistory.push(Math.round(ds.optionValue));
            ds.confidenceHistory.push(Math.round(ds.boardConfidence));
            ds.npvHistory.push(Math.round(ds.portfolioNPV));
            ds.strandedHistory.push(Math.round(ds.strandedRisk));

            var results = {
                period: state.currentPeriod,
                roundIdx: roundIdx,
                primaryFocus: d.primaryFocus,
                secondaryFocus: d.secondaryFocus,
                capitalCommit: commit,
                optionalityReserve: reserve,
                narrativeApproach: d.narrativeApproach,
                foresightDelta: Math.round(foresightDelta),
                robustnessDelta: Math.round(robustnessDelta),
                optionDelta: Math.round(optionDelta),
                confidenceDelta: Math.round(confidenceDelta),
                npvDelta: Math.round(npvDelta),
                strandedDelta: Math.round(strandedDelta),
                foresightQuality: Math.round(ds.foresightQuality),
                strategicRobustness: Math.round(ds.strategicRobustness),
                optionValue: Math.round(ds.optionValue),
                boardConfidence: Math.round(ds.boardConfidence),
                portfolioNPV: Math.round(ds.portfolioNPV),
                strandedRisk: Math.round(ds.strandedRisk),
                activeEvent: eventKey
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });
                self._showEvent(eventKey);
                self._renderHint(state, results);
            }, 450);

            return results;
        }

        _rollEvent(roundIdx) {
            if (roundIdx === 2) {
                if (Math.random() < 0.7) return `cbam_regulatory`;
            } else if (roundIdx === 3) {
                if (Math.random() < 0.6) return `tech_breakthrough`;
                if (Math.random() < 0.3) return `geopolitical_shock`;
            } else if (roundIdx === 4) {
                if (Math.random() < 0.65) return `black_swan`;
            }
            return null;
        }

        _showEvent(eventKey) {
            var panel = document.getElementById(`eventPanel`);
            var titleEl = document.getElementById(`eventTitle`);
            var textEl = document.getElementById(`eventText`);
            if (!panel || !titleEl || !textEl) return;
            if (!eventKey) {
                panel.style.display = `none`;
                return;
            }
            var t = window.mySimulation.t.bind(window.mySimulation);
            titleEl.textContent = t(`event_title_` + eventKey);
            textEl.textContent = t(`event_text_` + eventKey);
            panel.style.display = `block`;
        }

        _renderHint(state, results) {
            var box = document.getElementById(`hintBox`);
            var txt = document.getElementById(`hintText`);
            if (!box || !txt) return;
            var hint = this.getHint(state, results);
            if (hint) {
                txt.textContent = hint;
                box.style.display = `block`;
            } else {
                box.style.display = `none`;
            }
        }

