        getHint(state, results) {
            if (!results) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (results.strandedDelta >= 40) return t(`hint_stranded_spike`);
            if (results.roundIdx === 2 && results.primaryFocus !== `balanced`) return t(`hint_scenario_narrow`);
            if (results.roundIdx === 3 && (results.primaryFocus === `harvest` || results.primaryFocus === `gas_bridge`)) return t(`hint_robustness_trap`);
            if (results.roundIdx === 4 && results.secondaryFocus === `ad_hoc`) return t(`hint_governance_weak`);
            if (state.domainState.strategicRobustness < 40) return t(`hint_low_robust`);
            if (state.domainState.foresightQuality < 40) return t(`hint_low_foresight`);
            if (state.domainState.boardConfidence < 40) return t(`hint_low_confidence`);
            if (state.domainState.optionValue < 30 && results.roundIdx >= 2) return t(`hint_option_starved`);
            return null;
        }

